import{_ as i,o as t,c as a,ag as s}from"./chunks/framework.D9ghT4bC.js";const u=JSON.parse('{"title":"The UncivCN Branch","description":"","frontmatter":{},"headers":[],"relativePath":"UncivCN/index.md","filePath":"UncivCN/index.md"}'),r={name:"UncivCN/index.md"};function n(l,e,o,d,h,p){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="the-uncivcn-branch" tabindex="-1">The UncivCN Branch <a class="header-anchor" href="#the-uncivcn-branch" aria-label="Permalink to &quot;The UncivCN Branch&quot;">​</a></h1><h2 id="what-is-this" tabindex="-1">What is this? <a class="header-anchor" href="#what-is-this" aria-label="Permalink to &quot;What is this?&quot;">​</a></h2><p><strong>UncivCN</strong> is a community fork of the open source game <a href="https://github.com/yairm210/Unciv" target="_blank" rel="noreferrer">Unciv</a> (a Civ V remake in LibGDX, supporting Android / Desktop / Server), deeply customized for Chinese-speaking players: it adds multiplayer, map, modding and UI features on top of the original, while staying fully in sync with upstream updates.</p><ul><li>Upstream repository: <a href="https://github.com/yairm210/Unciv" target="_blank" rel="noreferrer">https://github.com/yairm210/Unciv</a></li><li>UncivCN repository: <a href="https://github.com/AutumnPizazz/Unciv" target="_blank" rel="noreferrer">https://github.com/AutumnPizazz/Unciv</a></li><li>Current version: <strong>4.21.6.3</strong> (based on upstream 4.21.6)</li></ul><h2 id="relationship-with-upstream" tabindex="-1">Relationship with upstream <a class="header-anchor" href="#relationship-with-upstream" aria-label="Permalink to &quot;Relationship with upstream&quot;">​</a></h2><ul><li><strong>In sync</strong>: upstream master is merged into UncivCN regularly. Version number = upstream version + CN sub-version (e.g. 4.21.5 → 4.21.5.1; the same upstream version can have multiple CN sub-versions .1/.2/.3…, e.g. 4.20.8.1 → 4.20.8.4), always tracking the latest upstream development</li><li><strong>Additive changes</strong>: all UncivCN features are implemented incrementally; upstream behavior is unaffected</li><li><strong>Fork point</strong>: UncivCN has evolved independently since 2026 (<a href="https://github.com/AutumnPizazz/Unciv/commit/4c23bb4dc" target="_blank" rel="noreferrer">4c23bb4dc</a>), with its own versioning and release cadence</li></ul><h2 id="feature-overview" tabindex="-1">Feature overview <a class="header-anchor" href="#feature-overview" aria-label="Permalink to &quot;Feature overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Features</th></tr></thead><tbody><tr><td>Multiplayer</td><td><a href="./Polling-multiplayer.html">Polling multiplayer</a>, default server (sp.unciv.cn), save-scumming RNG disabled online</td></tr><tr><td>Maps</td><td>Three mirrored map modes, wraparound (ring) maps, no radius parity restriction</td></tr><tr><td>Modding</td><td><a href="./Features.html#lua-scripting-since-4-20-8-2-continuously-extended">Lua scripting</a>, <a href="./Features.html#mergeaction-extended-json-system-4-20-7-3">MergeAction extended JSON</a>, tile-claim</td></tr><tr><td>UI</td><td>Unit pins / map pins, auto-lock citizens button, export/import game settings to clipboard</td></tr><tr><td>Other</td><td>Save version isolation, RNG re-rollable on load (single-player)</td></tr></tbody></table><p>Details in <a href="./Features.html">Features</a> and <a href="./Differences.html">Differences vs upstream</a>.</p><h2 id="building" tabindex="-1">Building <a class="header-anchor" href="#building" aria-label="Permalink to &quot;Building&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop:run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # run desktop version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :tests:test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # run all tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop:dist</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # build JAR → desktop/build/libs/Unciv.jar</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server:run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # run multiplayer server</span></span></code></pre></div><p>Android builds need <code>local.properties</code> (<code>sdk.dir</code>) or the <code>ANDROID_HOME</code> environment variable.</p><p>The version is defined in <code>buildSrc/src/main/kotlin/BuildConfig.kt</code>; changes are tracked in <a href="./Changelog.html">Changelog</a>.</p>`,13)])])}const m=i(r,[["render",n]]);export{u as __pageData,m as default};
